{"command":"D="/home/user/deepseek-harness/.code-safety/NodeGoat-base-b/repo/program-e570066f04d23255d2013278e0ba6258138c9ec2f50b7ee6592b34b6329a7b5c/@integration"
cd "$D"
node -e '
const fs = require("fs");
const files = ["access","data","dependencies","injection","platform","secrets"];
const all = [];
for (const f of files) {
  const arr = JSON.parse(fs.readFileSync(`findings/${f}.json`, "utf8"));
  for (const finding of arr) all.push({dept: f, finding});
}
console.log("total raw:", all.length);
const dropIds = new Set(["access-session-fixation-login","data-007","secrets-cookie-secret","platform-006-error-handler-exposes-error","secrets-crypto-key-dead-code"]);
const kept = all.filter(x => !dropIds.has(x.finding.id));
console.log("kept:", kept.length);
// check dedup key
const keys = new Map();
for (const {finding} of kept) {
  const k = `${finding.file}:${finding.line}:${finding.cwe}`;
  if (keys.has(k)) console.log("DUP KEY REMAINS:", k, keys.get(k), finding.id);
  keys.set(k, finding.id);
}
// severity counts
const sev = {};
for (const {finding} of kept) sev[finding.severity] = (sev[finding.severity]||0)+1;
console.log(sev);
fs.writeFileSync("/tmp/kept_ids.json", JSON.stringify(kept.map(x=>x.finding.id), null, 2));
fs.writeFileSync("findings.json", JSON.stringify(kept.map(x=>x.finding), null, 2) + "\n");
'
","description":"Build deduplicated findings.json from department files"}

